42	    HcclCMDType opType, const char* algName, const char* executorName, const char** templateName, int templateNum);
43	
44	typedef struct {
45	    float A; // 用来描述跨卡传输的时间随DataSize变化的趋势，会受到UB带宽利用率的影响
46	    float B; // 用来描述本地传输的时间随DataSize变化的趋势，不受到UB带宽利用率的影响
47	    float C; // 用来描述一些基本时延的常数项
48	} CostModelParam;
49	
50	typedef struct {
51	    const char* algName;
52	    // 所有权：param 指向的内存由 costModel_ 持有（InitCostModel 深拷贝）。
53	    // FreeCostModel 会逐个释放 param 指向的内存。
54	    const CostModelParam* param;
55	    int count;
56	} CostAlgoParams;
57	
58	typedef struct {
59	    CostAlgoParams* costAlgoParams;
60	    int count;
61	} CostModel;
62	
63	enum class EngineType : int {
64	    AICPU = 0,
65	    CCU = 1,
66	    CCU_CIR_MODE = 2,
67	    AIV = 3,
68	    CPU = 4,
69	};
70	
71	enum class AlgNetType : int {
72	    MESH = 0, // mesh 组网
73	    CLOS = 1, // clos 组网
74	};
75	
76	class CostModelManager {
77	public:
78	    struct RankSizePerLevel {
79	        u32 level0 = 0;
80	        u32 level1 = 0;
81	        u32 level2 = 0;
82	    };
83	
84	    CostModelManager();
85	    ~CostModelManager() = default;
86	    static CostModelManager* Global();
87	
88	    HcclResult InitCostModel(HcclComm comm, TopoInfoWithNetLayerDetails* topoInfo, CostModel& costModel);
89	    static void FreeCostModel(CostModel& costModel);
90	    void InitBandwidth();
91	    RankSizePerLevel CalcRankSizeByTopo(const TopoInfoWithNetLayerDetails* topoInfo) const;
92	
93	    // n: 每次发送数据量占总数据量的比例
94	    // netType: 组网类型（mesh组网或clos组网）0:mesh组网 1:clos组网
95	    // portNum: clos组网下使用的端口数量，mesh组网时为0
96	    // A: 出参，接收计算得到的A值
97	    // 计算Mesh算法的A参数
98	    void CalcMeshParam(float n, AlgNetType netType, int portNum, u32 rankSize, float& A);
99	    // 计算NHR算法的A参数
100	    void CalcNHRParams(float n, AlgNetType netType, int portNum, u32 rankSize, float& A);
101	    // n: 输入数据占总数据量DataSize的比例
102	    // B: 出参，接收计算得到的B值
103	    // 计算本地拷贝的B参数
104	    void CalcLocalCopyParams(float n, EngineType scene, float& B);
105	    // 计算本地reduce的B参数
106	    void CalcLocalReduceParams(float n, EngineType scene, float& B);
107	    // 计算Latency参数, taskNum需要写算法的人预估
108	    void CalcLatencyParams(int taskNum, EngineType engine, float& C);
109	
110	private:
111	    // 带宽的单位都是GB/s
112	    float localCopyBw_{};            // 本地拷贝带宽
113	    float localReduceBw_{};          // 本地reduce带宽
114	    float crossChipBw_{};            // 跨片带宽
115	    float crossChipReduceBw_{};      // 跨片reduce带宽
116	    float ccuLocalCopyBw_{};         // ccu场景本地拷贝带宽
117	    float ccuLocalReduceBw_{};       // ccu场景本地reduce带宽
118	    float ccuCircleLocalCopyBw_{};   // ccu环形场景本地拷贝带宽
119	    float ccuCircleLocalReduceBw_{}; // ccu环形场景本地reduce带宽
120	};
121	
122	enum class CostAggMode : int {
123	    SUM = 0, // 多组 cost 求和
124	    MAX = 1, // 多组 cost 取最大值
125	};
126	
127	// CalcCostCoeff 的参数结构体，新增参数只需在此结构体加成员，无需改动所有调用点签名
128	struct CalcCostCoeffParam {
129	    u32 rankSize = 0;
130	    float n = 0.0f;
131	    AlgNetType netType = AlgNetType::MESH;
132	    bool needLocalCopy = true;
