10	
11	#include "cost_model.h"
12	
13	#include <new>
14	#include <memory>
15	
16	#include "coll_alg_v2_exec_registry.h"
17	
18	namespace ops_hccl {
19	
20	AllAlgos* GetAllAlgos()
21	{
22	    static AllAlgos globalAllAlgos{nullptr, 0, 0};
23	    return &globalAllAlgos;
24	}
25	
26	HcclResult AddAlgToAllAlgos(
27	    HcclCMDType opType, const char* algName, const char* executorName, const char** templateName, int templateNum)
28	{
29	    AllAlgos* allAlgos = GetAllAlgos();
30	    if (allAlgos->count >= allAlgos->capacity) {
31	        int newCapacity = (allAlgos->capacity == 0) ? 16 : allAlgos->capacity * 2;
32	        AlgElement* newElements = new (std::nothrow) AlgElement[newCapacity];
33	        if (newElements == nullptr) {
34	            HCCL_ERROR("[AllAlgos] alloc failed, newCapacity=%d.", newCapacity);
35	            return HcclResult::HCCL_E_PARA;
36	        }
37	        for (int i = 0; i < allAlgos->count; ++i) {
38	            newElements[i] = allAlgos->algElements[i];
39	        }
40	        delete[] allAlgos->algElements;
41	        allAlgos->algElements = newElements;
42	        allAlgos->capacity = newCapacity;
43	    }
44	    allAlgos->algElements[allAlgos->count] = {algName, executorName, templateName, templateNum, opType};
45	    ++allAlgos->count;
46	    HCCL_DEBUG(
47	        "[AllAlgos] add algName=%s executorName=%s templateNum=%d opType=%d, total=%d.", algName, executorName,
48	        templateNum, opType, allAlgos->count);
49	    return HcclResult::HCCL_SUCCESS;
50	}
51	
52	CostModelManager::CostModelManager() { InitBandwidth(); }
53	
54	CostModelManager* CostModelManager::Global()
55	{
56	    static CostModelManager* globalCostModelManager = new CostModelManager;
57	    return globalCostModelManager;
58	}
59	
60	void CostModelManager::FreeCostModel(CostModel& costModel)
61	{
62	    if (costModel.costAlgoParams != nullptr) {
63	        for (int i = 0; i < costModel.count; ++i) {
64	            delete[] costModel.costAlgoParams[i].param;
65	            costModel.costAlgoParams[i].param = nullptr;
66	        }
67	        delete[] costModel.costAlgoParams;
68	        costModel.costAlgoParams = nullptr;
69	    }
70	    costModel.count = 0;
71	}
72	
73	void CostModelManager::InitBandwidth()
74	{
75	    HCCL_DEBUG("[CostModelManager] InitBandwidth.");
76	    localCopyBw_ = 750.0f * 1000 * 1000 * 1000;
77	    localReduceBw_ = 483.0f * 1000 * 1000 * 1000;
78	    crossChipBw_ = 56.0f * 1000 * 1000 * 1000;
79	    crossChipReduceBw_ = 56.0f * 1000 * 1000 * 1000;
80	    ccuLocalCopyBw_ = 200.0f * 1000 * 1000 * 1000;
81	    ccuLocalReduceBw_ = 160.0f * 1000 * 1000 * 1000;
82	    ccuCircleLocalCopyBw_ = 47.6f * 1024 * 1024 * 1024;
83	    ccuCircleLocalReduceBw_ = 47.6f * 1024 * 1024 * 1024;
84	    HCCL_DEBUG(
85	        "[CostModelManager] localCopyBw=%f localReduceBw=%f crossChipBw=%f crossChipReduceBw=%f "
86	        "ccuLocalCopyBw=%f ccuLocalReduceBw=%f ccuCircleLocalCopyBw=%f ccuCircleLocalReduceBw=%f.",
87	        localCopyBw_, localReduceBw_, crossChipBw_, crossChipReduceBw_, ccuLocalCopyBw_, ccuLocalReduceBw_,
88	        ccuCircleLocalCopyBw_, ccuCircleLocalReduceBw_);
89	}
90	
91	CostModelManager::RankSizePerLevel
92	CostModelManager::CalcRankSizeByTopo(const TopoInfoWithNetLayerDetails* topoInfo) const
93	{
94	    RankSizePerLevel rs;
95	    if (topoInfo == nullptr) {
96	        return rs;
97	    }
98	    rs.level0 = topoInfo->userRankSize;
99	    const auto& nd = topoInfo->netLayerDetails;
100	    // level0: 每个实例（server内mesh组）的rank数
101	    if (!nd.instSizeListOfLayer.empty() && !nd.instSizeListOfLayer[0].empty()) {
102	        rs.level0 = nd.instSizeListOfLayer[0][0];
103	    }
104	    // level1: 同序号跨pod的rank数 = 总rank / level0（即pod/server数）
105	    if (rs.level0 > 0) {
106	        rs.level1 = topoInfo->userRankSize / rs.level0;
107	    }
108	    // level2: 同序号跨super-pod的rank数 = 总rank / (level0 * level1)（即super-pod数）
109	    if (rs.level0 > 0 && rs.level1 > 0) {
110	        rs.level2 = topoInfo->userRankSize / (rs.level0 * rs.level1);
111	    }
112	    return rs;
113	}
114	
115	static bool IsAlgoMatchTopo(const std::string& algName, const TopoInfoWithNetLayerDetails* topoInfo, HcclCMDType opType)
116	{
117	    bool isMultiLevel = algName.find("Parallel") != std::string::npos || algName.find("Sequence") != std::string::npos
118	                        || algName.find("Concur") != std::string::npos || algName.find("MultiLink") != std::string::npos
119	                        || algName.find("OmniPipe") != std::string::npos;
120	    bool is3Level;
121	    if (opType == HcclCMDType::HCCL_CMD_ALLGATHER) {
122	        // AllGather: SequenceMeshConcurNHR 是 2 级算法, ParallelNHRNHR/ConcurNHRNHR/PipeLine/PipeLineMeshNHRNHR 是 3 级
123	        is3Level = algName.find("ParallelNHRNHR") != std::string::npos
124	                   || algName.find("ConcurNHRNHR") != std::string::npos
125	                   || algName.find("PipeLine") != std::string::npos;
126	    } else {
127	        is3Level = algName.find("SequenceMeshConcur") != std::string::npos;
128	    }
129	
130	    if (topoInfo->topoLevelNums == 1) {
131	        if (isMultiLevel || is3Level) {
132	            return false;
133	        }
134	    } else if (topoInfo->topoLevelNums == 2) {
135	        if (is3Level) {
136	            return false;
137	        }
138	    } else if (topoInfo->topoLevelNums == 3) {
139	        bool oneCardPerServer = !topoInfo->netLayerDetails.localNetInsSizeOfLayer.empty()
140	                                && topoInfo->netLayerDetails.localNetInsSizeOfLayer[0] == 1;
141	        if (oneCardPerServer) {
142	            if (isMultiLevel && !is3Level) {
143	                return false;
144	            }
145	        } else {
146	            if (!is3Level) {
147	                return false;
148	            }
149	        }
150	    }
151	
152	    return true;
153	}
