155	HcclResult CostModelManager::InitCostModel(HcclComm comm, TopoInfoWithNetLayerDetails* topoInfo, CostModel& costModel)
156	{
157	    const AllAlgos& allAlgos = *GetAllAlgos();
158	    int algNum = allAlgos.count;
159	    if (algNum <= 0) {
160	        HCCL_WARNING("[CostModelManager] InitCostModel with empty AllAlgos.");
161	        return HcclResult::HCCL_SUCCESS;
162	    }
163	
164	    costModel.costAlgoParams = new (std::nothrow) CostAlgoParams[algNum];
165	    if (costModel.costAlgoParams == nullptr) {
166	        HCCL_ERROR("[CostModelManager] alloc CostAlgoParams failed, algNum=%d.", algNum);
167	        return HcclResult::HCCL_E_PARA;
168	    }
169	    costModel.count = 0;
170	
171	    for (int i = 0; i < algNum; ++i) {
172	        const AlgElement& alg = allAlgos.algElements[i];
173	        std::string algName = (alg.algName != nullptr) ? alg.algName : "";
174	
175	        if (!IsAlgoMatchTopo(algName, topoInfo, alg.opType)) {
176	            HCCL_DEBUG("[CostModelManager] algName=%s skipped by topo filter.", algName.c_str());
177	            continue;
178	        }
179	
180	        std::unique_ptr<InsCollAlgBase> exec = CollAlgExecRegistryV2::Instance().GetAlgExec(alg.opType, alg.algName);
181	        if (exec == nullptr) {
182	            HCCL_WARNING(
183	                "[CostModelManager] executor not registered, skip algName=%s opType=%d.", alg.algName, alg.opType);
184	            continue;
185	        }
186	
187	        std::vector<CostModelParam> params = exec->CalcCostCoeff(comm, topoInfo, alg.algName);
188	        if (params.empty()) {
189	            HCCL_WARNING("[CostModelManager] CalcCostCoeff uncalibrated, skip algName=%s.", alg.algName);
190	            continue;
191	        }
192	        int paramCount = static_cast<int>(params.size());
193	
194	        // 深拷贝 param 到堆，costModel 持有独立内存所有权
195	        CostModelParam* ownedParam = new (std::nothrow) CostModelParam[paramCount];
196	        if (ownedParam == nullptr) {
197	            HCCL_ERROR("[CostModelManager] alloc ownedParam failed, algName=%s count=%d.", alg.algName, paramCount);
198	            continue;
199	        }
200	        std::copy(params.begin(), params.end(), ownedParam);
201	
202	        AlgNetMetaRegistry::Global()->Register(alg.algName, exec->GetAlgNetMeta(topoInfo));
203	
204	        CostAlgoParams cap;
205	        cap.algName = alg.algName;
206	        cap.param = ownedParam;
207	        cap.count = paramCount;
208	        costModel.costAlgoParams[costModel.count] = cap;
209	        ++costModel.count;
210	    }
211	
212	    if (costModel.count == 0) {
213	        delete[] costModel.costAlgoParams;
214	        costModel.costAlgoParams = nullptr;
215	    }
216	
217	    HCCL_DEBUG("[CostModelManager] InitCostModel done, total=%d calibrated=%d.", algNum, costModel.count);
218	    return HcclResult::HCCL_SUCCESS;
219	}
