226	        // cost = D/B(write)
227	        A = n / crossChipBw_;
228	    } else if (netType == AlgNetType::CLOS) {
229	        // cost = nD/B(write)
230	        A = (n * (rankSize - 1)) / (portNum * crossChipBw_);
231	    } else {
232	        HCCL_ERROR("[CostModelManager] CalcMeshParams unsupported netType=%d.", static_cast<int>(netType));
233	    }
