242	    // rankSize是指总共通信的rankSize
243	    A = 0.0f;
244	    float data = n * (rankSize - 1);
245	    if (netType == AlgNetType::MESH) {
246	        A = data / crossChipBw_;
247	    } else if (netType == AlgNetType::CLOS) {
