35	    inline bool IsAgInputOutputOverlap(const OpParam& op)
36	    {
37	        if (op.inputPtr == nullptr || op.outputPtr == nullptr || op.inputSize == 0 || op.outputSize == 0) {
38	            return false;
39	        }
40	        uintptr_t inStart = reinterpret_cast<uintptr_t>(op.inputPtr);
41	        uintptr_t outStart = reinterpret_cast<uintptr_t>(op.outputPtr);
42	        return inStart <= outStart + op.outputSize - 1 && outStart <= inStart + op.inputSize - 1;
43	    }
