410	             },
411	             false, ccuAivAll},
412	            // 必不选：64bit(INT64/UINT64/FP64) 排除 ccu + aiv
413	            {"64bit_skip_ccu_aiv",
414	             [](const OpParam& op, const TopoInfoWithNetLayerDetails*) {
415	                 return Is64BitDataType(op.DataDes.dataType);
416	             },
417	             false, ccuAivAll},
418	            // 必不选：保序模式排除 ccu + aiv
419	            {"order_preserved_skip_ccu_aiv",
420	             [](const OpParam& op, const TopoInfoWithNetLayerDetails* topo) {
421	                 return IsNeedStrictModeForOrderPreserved(op, topo->userRankSize);
422	             },
423	             false, ccuAivAll},
424	            // 必不选：level2Ubg 排除 aiv + ccu_sched
425	            {"level2ubg_skip_aiv_ccu_sched",
426	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
427	                 return topo->level2Ubg;
428	             },
429	             false, aivCcuSched},
430	            // 必不选：3级拓扑 + level2Uboe 排除 aiv + ccu_sched
431	            {"level2uboe_skip_aiv_ccu_sched",
432	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
433	                 return topo->topoLevelNums == TOPO_LEVEL_NUM_3 && topo->level2Uboe;
434	             },
435	             false, aivCcuSched},
436	            // 必不选：ccu_ms 仅支持单级拓扑，多级拓扑排除
437	            {"ccu_ms_single_level_only",
438	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
439	                 return topo->topoLevelNums > 1;
440	             },
441	             false, ccuMsAlgos},
442	            // 必不选：2Die 算法仅在 TWO_DIE_REGULAR 拓扑下可选
443	            {"two_die_regular_only",
444	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
445	                 return topo->level0MeshType != Level0MeshType::TWO_DIE_REGULAR;
446	             },
447	             false, twoDieAlgos},
448	            // 必不选：parallel/sequence/concurrent/omnipipe 算法仅在多级拓扑(topoLevelNums>1)下可选
449	            {"multilevel_only",
450	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
451	                 return topo->topoLevelNums == 1;
452	             },
453	             false, multilevelAlgos},
454	            // 必不选：UBX/Pcie/Uboe 专用算法仅在 MESH_1D_CLOS(UBX) 拓扑下可选
455	            {"ubx_only",
456	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
457	                 return topo->level0Topo != Level0Shape::MESH_1D_CLOS;
458	             },
459	             false, ubxOnlyAlgos},
460	            // ── 资源硬约束（旧路径 NOT_MATCH 降级，新路径 must-not-select 排除）──
461	            // 必不选：frameNum > 16 时排除 CCU mesh 类算法（kernel repeatNum 上限）
462	            // 旧路径 reduce_scatter_auto_selector.cc:259-264 回退到 CcuSchedReduceScatterSoleNHR
463	            {"ccu_frame_num_limit",
464	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
465	                 return AutoSelectorBase::CalcFrameNum(topo) > 16;
466	             },
467	             false, ccuMeshAlgos},
468	            // 必不选：AIV 数据量超限排除 AIV 算法
469	            // 旧路径 reduce_scatter_auto_selector.cc:594-605 (totalSize >= 8MB*rankSize 或 > cclBuffer*16)
470	            {"aiv_data_size_limit",
471	             [](const OpParam& op, const TopoInfoWithNetLayerDetails* topo) {
472	                 u64 perDataSize = DATATYPE_SIZE_TABLE[op.DataDes.dataType];
473	                 u64 totalSize = op.DataDes.count * perDataSize * topo->userRankSize;
474	                 if (op.opExecuteConfig != OpExecuteConfig::AIV_ONLY
475	                     && totalSize >= 8 * 1024 * 1024 * topo->userRankSize) {
476	                     return true;
477	                 }
478	                 void* cclBufferAddr = nullptr;
479	                 uint64_t cclBufferSize = 0;
480	                 if (HcclGetHcclBuffer(op.hcclComm, &cclBufferAddr, &cclBufferSize) == HCCL_SUCCESS) {
481	                     return totalSize > cclBufferSize * 16;
482	                 }
483	                 return false;
484	             },
485	             false, aivAlgos},
486	            // 必不选：AIV rankSize 超限排除 AIV 算法（kernel 硬编码 MAX_RANK_SIZE=2048）
487	            // 旧路径 reduce_scatter_auto_selector.cc:579-583
488	            {"aiv_rank_size_limit",
489	             [](const OpParam&, const TopoInfoWithNetLayerDetails* topo) {
490	                 return topo->userRankSize > 2048;
491	             },
492	             false, aivAlgos},
493	        };
494	    }
