502	HcclResult CostTableManager::FilterCMByConfig(
503	    CostModel& cm, CostTable& ct, const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam)
504	{
505	    HCCL_DEBUG(
506	        "[FilterCMByConfig] filter cost model by config, opType=%d, algCount=%d.", static_cast<int>(opParam.opType),
507	        cm.count);
508	    switch (opParam.opType) {
509	        case HcclCMDType::HCCL_CMD_ALLREDUCE:
510	            return FilterAllReduce(cm, ct, topoInfo, opParam);
511	        case HcclCMDType::HCCL_CMD_ALLGATHER:
512	            return FilterAllGather(cm, ct, topoInfo, opParam);
513	        case HcclCMDType::HCCL_CMD_REDUCE_SCATTER:
514	            return FilterReduceScatter(cm, ct, topoInfo, opParam);
515	        default:
516	            HCCL_WARNING(
517	                "[FilterCMByConfig] opType=%d not supported yet, keep all algorithms.",
518	                static_cast<int>(opParam.opType));
519	            return HcclResult::HCCL_SUCCESS;
520	    }
521	}
