523	void CostTableManager::DumpCostTable(const CostTable& ct)
524	{
525	    HCCL_INFO("====== [DFX_CostTableDump] algoCount=%d ======", ct.count);
526	    for (int i = 0; i < ct.count; ++i) {
527	        const char* name = (ct.costs[i].algName != nullptr) ? ct.costs[i].algName : "";
528	        HCCL_INFO("  [DFX_CostTableDump] [%d/%d] algName=%s, cost=%.6f", i + 1, ct.count, name, ct.costs[i].cost);
529	    }
530	    HCCL_INFO("====== [DFX_CostTableDump] dump end ======");
531	}
