533	HcclResult CostTableManager::FilterByRules(
534	    CostModel& cm, CostTable& ct, const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
535	    const std::vector<AlgFilterRule>& rules, const std::string& tag)
536	{
537	    HCCL_INFO("[%s] filter, algCount=%d.", tag.c_str(), cm.count);
538	    ct.costs = nullptr;
539	    ct.count = 0;
540	    if (cm.count <= 0) {
541	        return HcclResult::HCCL_SUCCESS;
542	    }
543	    ct.costs = new (std::nothrow) AlgoCost[cm.count]();
544	    if (ct.costs == nullptr) {
545	        HCCL_ERROR("[%s] alloc AlgoCost failed, count=%d.", tag.c_str(), cm.count);
546	        return HcclResult::HCCL_E_PARA;
547	    }
548	
549	    u64 dataSize = opParam.DataDes.count * DATATYPE_SIZE_TABLE[opParam.DataDes.dataType];
550	
551	    const char* opTypePascal = HcclOpTypeToPascal(opParam.opType);
552	
553	    std::set<std::string> mustSelect;
554	    for (const auto& rule : rules) {
555	        if (rule.isMustSelect && rule.condition(opParam, topoInfo)) {
556	            mustSelect.insert(rule.algos.begin(), rule.algos.end());
557	        }
558	    }
559	    if (!mustSelect.empty()) {
560	        for (int i = 0; i < cm.count; ++i) {
561	            if (cm.costAlgoParams[i].count <= 0) {
562	                continue;
563	            }
564	            const char* algName = cm.costAlgoParams[i].algName;
565	            std::string name = (algName != nullptr) ? algName : "";
566	            if (mustSelect.count(name) == 0) {
567	                continue;
568	            }
569	            float cost = CalcAlgCost(name, dataSize, cm.costAlgoParams[i], opParam.opType);
570	            ct.costs[ct.count].algName = algName;
571	            ct.costs[ct.count].cost = cost;
572	            ++ct.count;
573	        }
574	        HCCL_INFO("[%s] mustSelect matched, count=%d.", tag.c_str(), ct.count);
575	        DumpCostTable(ct);
576	        return HcclResult::HCCL_SUCCESS;
577	    }
578	
579	    std::set<std::string> mustNotSelect;
580	    std::map<std::string, std::string> filteredByRule;
581	    for (const auto& rule : rules) {
582	        if (!rule.isMustSelect && rule.condition(opParam, topoInfo)) {
583	            for (const auto& algo : rule.algos) {
584	                mustNotSelect.insert(algo);
585	                filteredByRule[algo] = rule.name;
586	            }
587	        }
588	    }
589	    bool isAivOnly = (opParam.commOpExpansionMode == HcclOpExpansionMode::HCCL_OP_EXPANSION_AIV_ONLY);
590	    for (int i = 0; i < cm.count; ++i) {
591	        if (cm.costAlgoParams[i].count <= 0) {
592	            continue;
593	        }
594	        const char* algName = cm.costAlgoParams[i].algName;
595	        std::string name = (algName != nullptr) ? algName : "";
596	        if (opTypePascal != nullptr && name.find(opTypePascal) == std::string::npos) {
597	            HCCL_INFO(
598	                "[%s] algName=%s filtered out by op-type mismatch (expected %s).", tag.c_str(), name.c_str(),
599	                opTypePascal);
600	            continue;
601	        }
602	        if (mustNotSelect.count(name) > 0) {
603	            std::string ruleName = filteredByRule.count(name) > 0 ? filteredByRule[name] : "unknown";
604	            if (isAivOnly && SelectorEngine::GetEngineByAlgName(name) == OpExecuteConfig::AIV) {
605	                HCCL_ERROR(
606	                    "[%s] AIV_ONLY: algName=%s filtered out by rule[%s].", tag.c_str(), name.c_str(), ruleName.c_str());
607	            } else {
608	                HCCL_DEBUG("[%s] algName=%s filtered out by rule[%s].", tag.c_str(), name.c_str(), ruleName.c_str());
609	            }
610	            continue;
611	        }
612	        float cost = CalcAlgCost(name, dataSize, cm.costAlgoParams[i], opParam.opType);
613	        ct.costs[ct.count].algName = algName;
614	        ct.costs[ct.count].cost = cost;
615	        ++ct.count;
616	        HCCL_INFO("[%s] algName=%s cost=%f.", tag.c_str(), name.c_str(), cost);
617	    }
618	    DumpCostTable(ct);
619	    return HcclResult::HCCL_SUCCESS;
620	}
