640	float CostTableManager::CalcAlgCost(
641	    const std::string& algName, u64 dataSize, const CostAlgoParams& algoParams, HcclCMDType opType) const
642	{
643	    AlgNetMeta meta;
644	    AlgNetMetaRegistry::Global()->Query(algName, meta);
645	
646	    OpExecuteConfig engine = SelectorEngine::GetEngineByAlgName(algName);
647	
648	    const CostModelParam* params = algoParams.param;
649	    std::vector<u32> groups = meta.groupSizes;
650	    if (groups.empty()) {
651	        groups.assign(static_cast<size_t>(algoParams.count), 1);
652	    }
653	
654	    std::vector<float> utils(static_cast<size_t>(algoParams.count), 1.0f);
655	    float cost = 0.0f;
656	    u32 idx = 0;
657	    for (u32 g = 0; g < groups.size() && idx < static_cast<u32>(algoParams.count); ++g) {
658	        float groupCost = 0.0f;
659	        for (u32 k = 0; k < groups[g] && idx < static_cast<u32>(algoParams.count); ++k, ++idx) {
660	            AlgNetType nt = (idx < meta.netTypes.size()) ? meta.netTypes[idx] : AlgNetType::MESH;
661	            float util = 1.0f;
662	            if (QueryUbUtil(nt, dataSize, engine, util, opType) != HcclResult::HCCL_SUCCESS) {
663	                util = 1.0f;
664	            }
665	            utils[idx] = util;
666	            float abCost = (params[idx].A / util + params[idx].B) * static_cast<float>(dataSize);
667	            float segCost = abCost + params[idx].C;
668	            groupCost = (meta.intraGroupMode == CostAggMode::MAX) ? std::max(groupCost, segCost) : groupCost + segCost;
669	        }
670	        cost += groupCost;
671	    }
672	    if (engine == OpExecuteConfig::AICPU_TS && opType != HcclCMDType::HCCL_CMD_ALLGATHER) {
673	        cost = std::max(cost, 0.0005f);
674	    }
675	    std::string paramInfo;
676	    char buf[64];
677	    for (int j = 0; j < algoParams.count; ++j) {
678	        if (snprintf_s(buf, sizeof(buf), sizeof(buf) - 1, "%e", params[j].A) < 0) {
679	            buf[0] = '\0';
680	        }
681	        std::string aStr = buf;
682	        if (snprintf_s(buf, sizeof(buf), sizeof(buf) - 1, "%e", params[j].B) < 0) {
683	            buf[0] = '\0';
684	        }
685	        std::string bStr = buf;
686	        if (snprintf_s(buf, sizeof(buf), sizeof(buf) - 1, "%e", params[j].C) < 0) {
687	            buf[0] = '\0';
688	        }
689	        std::string cStr = buf;
690	        paramInfo += " [A=" + aStr + " B=" + bStr + " C=" + cStr + " util=" + std::to_string(utils[j]) + "]";
691	    }
692	    HCCL_INFO(
693	        "[CalcAlgCost] algName=%s segCount=%d dataSize=%llu cost=%f params:%s.", algName.c_str(), algoParams.count,
694	        dataSize, cost, paramInfo.c_str());
695	    return cost;
696	}
