698	HcclResult CostTableManager::CostTableGen(
699	    CostModel& cm, CostTable& ct, const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam)
700	{
701	    HCCL_INFO("[CostTableGen] generate cost table, algCount=%d.", cm.count);
702	    HcclResult ret = FilterCMByConfig(cm, ct, topoInfo, opParam);
703	    if (ret != HcclResult::HCCL_SUCCESS) {
704	        HCCL_ERROR("[CostTableGen] FilterCMByConfig failed, ret=%d.", static_cast<int>(ret));
705	    }
706	    return ret;
707	}
