709	const std::vector<UbUtilEntry> CostTableManager::closUbUtilTable_
710	    = {{0.125 * 1024 * 1024ULL, 0.02755f}, {0.25 * 1024 * 1024ULL, 0.05357f}, {0.5 * 1024 * 1024ULL, 0.10388f},
711	       {1 * 1024 * 1024ULL, 0.1855f},      {2 * 1024 * 1024ULL, 0.3f},        {4 * 1024 * 1024ULL, 0.4288f},
712	       {8 * 1024 * 1024ULL, 0.5302f},      {16 * 1024 * 1024ULL, 0.568f},     {32 * 1024 * 1024ULL, 0.6549f},
713	       {64 * 1024 * 1024ULL, 0.7184f},     {128 * 1024 * 1024ULL, 0.7408f},   {256 * 1024 * 1024ULL, 0.7644f}};
714	
715	const std::vector<UbUtilEntry> CostTableManager::meshUbUtilTable_
716	    = {{1 * 1024 * 1024ULL, 0.7135f},  {2 * 1024 * 1024ULL, 0.7758f},   {4 * 1024 * 1024ULL, 0.8112f},
717	       {8 * 1024 * 1024ULL, 0.8301f},  {16 * 1024 * 1024ULL, 0.84f},    {32 * 1024 * 1024ULL, 0.8449f},
718	       {64 * 1024 * 1024ULL, 0.8475f}, {128 * 1024 * 1024ULL, 0.8487f}, {256 * 1024 * 1024ULL, 0.8494f}};
