721	
722	HcclResult CostTableManager::QueryUbUtil(
723	    AlgNetType netType, u64 dataSize, OpExecuteConfig engine, float& utilization, HcclCMDType opType) const
724	{
725	    const std::vector<UbUtilEntry>& table = (netType == AlgNetType::CLOS) ? closUbUtilTable_ : meshUbUtilTable_;
726	    if (table.empty()) {
727	        HCCL_WARNING(
728	            "[CostTableManager] ub util table empty, netType=%d dataSize=%llu.", static_cast<int>(netType), dataSize);
729	        return HcclResult::HCCL_E_PARA;
730	    }
731	    // AllGather: CLOS 小数据量(< 1MB)统一用 1MB 的 util
732	    if (opType == HcclCMDType::HCCL_CMD_ALLGATHER && netType == AlgNetType::CLOS && dataSize < 1 * 1024 * 1024ULL) {
733	        dataSize = 1 * 1024 * 1024ULL;
734	    }
735	    auto it = std::lower_bound(table.begin(), table.end(), dataSize, [](const UbUtilEntry& e, u64 ds) {
736	        return e.upperBound < ds;
737	    });
738	    if (it == table.end()) {
739	        utilization = table.back().utilization;
740	    } else {
741	        utilization = it->utilization;
742	    }
743	    if (engine == OpExecuteConfig::AIV) {
744	        utilization = utilization / 0.85f * 0.65f;
745	    }
746	    HCCL_DEBUG(
747	        "[CostTableManager] QueryUbUtil netType=%d dataSize=%llu engine=%d utilization=%f.", static_cast<int>(netType),
748	        dataSize, static_cast<int>(engine), utilization);
749	    return HcclResult::HCCL_SUCCESS;
750	}
