98	HcclResult InsTempAllReduceMesh1DOneShot::KernelRun(
99	    const OpParam& param, const TemplateDataParams& tempAlgParams, TemplateResource& templateResource)
100	{
101	    threadNum_ = templateResource.threads.size();
102	    processSize_ = tempAlgParams.sliceSize;
103	    count_ = tempAlgParams.count;
104	    dataType_ = param.DataDes.dataType;
105	    needAicpuReduce_
106	        = dataType_ == HcclDataType::HCCL_DATA_TYPE_INT64 || dataType_ == HcclDataType::HCCL_DATA_TYPE_UINT64
107	          || dataType_ == HcclDataType::HCCL_DATA_TYPE_FP64 || param.reduceType == HcclReduceOp::HCCL_REDUCE_PROD;
108	    HCCL_INFO("[InsTempAllReduceMesh1DOneShot] Run Start");
109	    CHK_PRT_RET(
110	        threadNum_ != templateRankSize_,
111	        HCCL_ERROR(
112	            "[InsTempAllReduceMesh1DOneShot][KernelRun] thread num is invalid, need[%u], actual[%u].",
113	            templateRankSize_, threadNum_),
114	        HcclResult::HCCL_E_INTERNAL);
115	
116	    RankSliceInfo sliceInfoVec;
117	    CHK_RET(CalcSlice(processSize_, sliceInfoVec));
118	    if (threadNum_ > 1) {
119	        std::vector<ThreadHandle> subThreads(templateResource.threads.begin() + 1, templateResource.threads.end());
120	        GetNotifyIdxMainToSub(notifyIdxMainToSub_);
121	        CHK_RET(PreSyncInterThreads(templateResource.threads[0], subThreads, notifyIdxMainToSub_));
122	    }
123	    CHK_RET(RunAllReduce(param, templateResource.channels, templateResource.threads, tempAlgParams, sliceInfoVec));
124	    if (threadNum_ > 1) {
125	        std::vector<ThreadHandle> subThreads(templateResource.threads.begin() + 1, templateResource.threads.end());
126	        GetNotifyIdxSubToMain(notifyIdxSubToMain_);
127	        CHK_RET(PostSyncInterThreads(templateResource.threads[0], subThreads, notifyIdxSubToMain_));
128	    }
129	    CHK_PRT(PostLocalReduce(param, templateResource.threads, tempAlgParams, sliceInfoVec));
130	    HCCL_INFO("[InsTempAllReduceMesh1DOneShot][KernelRun] AllReduceMesh1DOneShot finished: rank[%d] end", myRank_);
131	    return HCCL_SUCCESS;
132	}
133	
134	HcclResult InsTempAllReduceMesh1DOneShot::RunAllReduce(
135	    const OpParam& param, const std::map<u32, std::vector<ChannelInfo>>& channels,
136	    const std::vector<ThreadHandle>& threads, const TemplateDataParams& tempAlgParams,
137	    const RankSliceInfo& sliceInfoVec)
138	{
139	    HCCL_INFO("[InsTempAllReduceMesh1DOneShot][RunAllReduce] send/recv: rank[%d]", myRank_);
140	
141	    DataSlice usrInSlices
142	        = DataSlice(tempAlgParams.buffInfo.inputPtr, tempAlgParams.buffInfo.inBuffBaseOff, processSize_, count_);
143	    DataSlice usrOutSlices
144	        = DataSlice(tempAlgParams.buffInfo.outputPtr, tempAlgParams.buffInfo.outBuffBaseOff, processSize_, count_);
145	
146	    // 主流 - 本地拷贝
147	    CHK_RET(static_cast<HcclResult>(LocalCopy(threads[0], usrInSlices, usrOutSlices)));
148	
149	    // 特殊场景
150	    if (subCommRanks_[0].size() == 1) {
151	        return HCCL_SUCCESS;
152	    }
153	
154	    // 从流
155	    for (u32 queIdx = 1; queIdx < threadNum_; queIdx++) {
156	        u32 nextRank = (myRank_ + queIdx) % templateRankSize_;
157	        u32 fromRank = subCommRanks_[0][nextRank];
158	        u32 toRank = subCommRanks_[0][nextRank];
159	
160	        const ChannelInfo& linkRecv = channels.at(fromRank)[0]; // linkRecv - 从fromRank接收的链路
161	        const ChannelInfo& linkSend = channels.at(toRank)[0];   // linkSend - 向toRank发送的链路
162	
163	        std::vector<DataSlice> txSrcSlices;
164	        std::vector<DataSlice> txDstSlices;
165	        void* txCclBuffAddr = linkSend.remoteCclMem.addr;
166	        u64 txDstOffset = sliceInfoVec[myRank_][0].offset + tempAlgParams.buffInfo.hcclBuffBaseOff;
167	        u64 txDstSize = sliceInfoVec[myRank_][0].size;
168	        DataSlice txSrcSlice = usrInSlices;
169	        DataSlice txDstSlice = DataSlice(txCclBuffAddr, txDstOffset, txDstSize, count_);
170	        txSrcSlices.push_back(txSrcSlice);
171	        txDstSlices.push_back(txDstSlice);
172	
173	        std::vector<DataSlice> rxSrcSlices;
174	        std::vector<DataSlice> rxDstSlices;
175	        void* rxCclBuffAddr = linkRecv.remoteCclMem.addr;
176	        u64 rxDstOffset = sliceInfoVec[fromRank][0].offset + tempAlgParams.buffInfo.hcclBuffBaseOff;
177	        u64 rxDstSize = sliceInfoVec[fromRank][0].size;
178	        DataSlice rxSrcSlice = usrInSlices;
179	        DataSlice rxDstSlice = DataSlice(rxCclBuffAddr, rxDstOffset, rxDstSize, count_);
180	        rxSrcSlices.push_back(rxSrcSlice);
181	        rxDstSlices.push_back(rxDstSlice);
182	
183	        SendRecvInfo sendRecvInfo{
184	            {linkSend, linkRecv}, {{txSrcSlices, txDstSlices}, {rxSrcSlices, rxDstSlices}}, dataType_};
185	        CHK_PRT_RET(
186	            SendRecvBatchWrite(sendRecvInfo, threads[queIdx]),
187	            HCCL_ERROR("[InsTempAllReduceMesh1DOneShot] RunAllReduce SendRecv failed"), HcclResult::HCCL_E_INTERNAL);
188	    }
189	
190	    return HCCL_SUCCESS;
191	}
192	
193	HcclResult InsTempAllReduceMesh1DOneShot::PostLocalReduce(
194	    const OpParam& param, const std::vector<ThreadHandle>& threads, const TemplateDataParams& tempAlgParams,
195	    const RankSliceInfo& sliceInfoVec)
196	{
197	    HCCL_INFO("[InsTempAllReduceMesh1DOneShot][RunAllReduce] reduce: rank[%d]", myRank_);
198	    // 增加thread synchronize以支持64类数据类型
199	    if (needAicpuReduce_) {
200	        // 启动任务并等待所有threads任务执行完成
201	        CHK_RET(static_cast<HcclResult>(HcommBatchModeEnd(param.algTag)));
202	        CHK_RET(static_cast<HcclResult>(HcommBatchModeStart(param.algTag)));
203	        for (const auto& thread : threads) {
204	            CHK_RET(static_cast<HcclResult>(HcommThreadJoin(thread, CUSTOM_TIMEOUT)));
205	        }
206	    }
207	
208	    DataSlice usrOutSlices
209	        = DataSlice(tempAlgParams.buffInfo.outputPtr, tempAlgParams.buffInfo.outBuffBaseOff, processSize_, count_);
210	
211	    for (u32 rankIdx = 0; rankIdx < subCommRanks_[0].size(); rankIdx++) {
212	        u32 curRank = rankIdx;
213	        // 遍历除自身外所有rank，计算reduce(scratch, local-usrout)
214	        if (curRank == myRank_) {
215	            continue;
216	        }
217	
218	        // 执行本地归约
219	        void* RemotePtr = tempAlgParams.buffInfo.hcclBuff.addr;
220	        u64 curSrcOffset = sliceInfoVec[curRank][0].offset + tempAlgParams.buffInfo.hcclBuffBaseOff;
221	        u64 curSrcSize = sliceInfoVec[curRank][0].size;
222	        DataSlice curSrcSlice = DataSlice(RemotePtr, curSrcOffset, curSrcSize, count_);
223	        DataSlice curDstSlice = usrOutSlices;
224	
225	        CHK_RET(static_cast<HcclResult>(LocalReduce(threads[0], curSrcSlice, curDstSlice, dataType_, reduceOp_)));
226	    }
227	    return HCCL_SUCCESS;
228	}
229	
230	void InsTempAllReduceMesh1DOneShot::GetNotifyIdxMainToSub(std::vector<u32>& notifyIdxMainToSub)
231	{
232	    notifyIdxMainToSub.clear();
233	    u32 threadNum = templateRankSize_ > 1 ? templateRankSize_ : 1;
234	    u32 slaveThreadNum = threadNum - 1;
235	    for (u32 slaveThreadIdx = 0; slaveThreadIdx < slaveThreadNum; slaveThreadIdx++) {
236	        notifyIdxMainToSub.push_back(0);
237	    }
238	}
239	
240	void InsTempAllReduceMesh1DOneShot::GetNotifyIdxSubToMain(std::vector<u32>& notifyIdxSubToMain)
241	{
242	    notifyIdxSubToMain.clear();
243	    u32 threadNum = templateRankSize_ > 1 ? templateRankSize_ : 1;
244	    u32 notifyNum = threadNum - 1;
245	    for (u32 notifyIdx = 0; notifyIdx < notifyNum; notifyIdx++) {
246	        notifyIdxSubToMain.push_back(notifyIdx);
247	    }
248	}
